package com.example.starter.trace;

/**
 * 采收批状态：REGISTERED 已登记待检，RELEASED 已放行可进入加工，FROZEN 疑似冻结禁止加工。
 */
public enum BatchStatus {
    REGISTERED,
    RELEASED,
    FROZEN
}

package com.example.starter.trace;

/**
 * 检测结论：PASS 快检合格，SUSPECT 快检疑似（抑制率≥50%），
 * OVERTURNED 复检合格推翻快检，CONFIRMED 复检不合格确认疑似。
 */
public enum TestConclusion {
    PASS,
    SUSPECT,
    OVERTURNED,
    CONFIRMED
}

package com.example.starter.trace;

import org.springframework.http.HttpStatus;

/**
 * 业务异常，携带 HTTP 状态语义，由全局异常处理器转换为统一错误响应。
 */
public class BizException extends RuntimeException {

    private final HttpStatus status;

    public BizException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static BizException badRequest(String message) {
        return new BizException(HttpStatus.BAD_REQUEST, message);
    }

    public static BizException notFound(String message) {
        return new BizException(HttpStatus.NOT_FOUND, message);
    }

    public static BizException conflict(String message) {
        return new BizException(HttpStatus.CONFLICT, message);
    }
}

